 dict(section="Kill switch e canary", type="code", title="Rollout percentual estável por usuário", code=[
   "function inRollout(flag: string, userId: string, percent: number) {",
   "  const h = createHash('sha256').update(`${flag}:${userId}`).digest();",
   "  return h.readUInt32BE(0) % 100 < percent;",
   "}",
   "const route = inRollout('partner-bank-v2', user.id, config.partnerV2Percent)",
   "  ? partnerBankV2 : partnerBankV1;"], hl=[1, 2],
   notes=[("Kill switch: ops toggle como circuit breaker operado à mão", "red"),
          ("Canary: 1% aleatório, compare métricas de negócio, amplie se bom", "green"),
          ("Hash de flag + usuário: cada flag com coorte independente e estável", "acc")], beats=[
  (1, "Um toggle router com rollout percentual estável: faça o hash da flag com o I D do usuário, e compare com o percentual. O mesmo usuário cai sempre do mesmo lado, e o toggle point fica num lugar só."),
  (2, "Duas ideias amarram o módulo. Kill switches: ops toggles de longa duração que funcionam como um circuit breaker operado à mão. Num incidente, um operador desliga uma funcionalidade não essencial para poupar capacidade. É o load shedding de terça, feito por uma pessoa."),
  (3, "E canary release: ligue para uma pequena coorte aleatória, um por cento, compare as métricas de negócio com o resto, e amplie só se os números forem bons. Diferente de liberar primeiro para usuários internos, que são um grupo escolhido, não uma amostra."),
  (4, "Incluir o nome da flag no hash dá a cada flag uma coorte independente. Senão o mesmo um por cento azarado receberia todas as novidades ao mesmo tempo. No projeto, ops toggles para o breaker e o rate limiter deixam a comparação de antes e depois limpa."),
  ("P", "Pergunta: qual a diferença entre um canary release e liberar primeiro para os funcionários?"),
  (4, "O canary é uma amostra aleatória de clientes reais, comparada com o resto. Funcionários são um grupo escolhido, que não representa o uso real."),
 ]),
